import { INestApplication } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';

/**
 * API docs: http://localhost:3000/api/docs
 * DTO fields are generated by the @nestjs/swagger CLI plugin (nest-cli.json)
 * from TypeScript types + class-validator decorators => no manual @ApiProperty() needed.
 */
export function setupSwagger(app: INestApplication): void {
  const config = new DocumentBuilder()
    .setTitle('Medium API')
    .setDescription('RealWorld (Medium clone) backend API built with NestJS')
    .setVersion('1.0')
    .addBearerAuth() // "Authorize" button: paste the token (without the Bearer prefix)
    .build();
  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api/docs', app, document, {
    swaggerOptions: { persistAuthorization: true },
  });
}
